mapper.select:
select * from (
/*检索字段*/ select * from ( SELECT '03' statusValid, WTT.TOTLE_TRADE_ID, WTTA.MP_FINPROD_ID, WTT.TG_BUSI_TYPE tradeType, WTT.PS cashType, WTT.PORTFOLIO_ID, PP.PORTFOLIO_NAME, MCP.COUNTER_NAME, WTT.SEC_MANAGE_ACCT_ID, SSAI.SEC_ACCT_NAME, FP.FINPROD_MARKET_ID, FP.FINPROD_ID, WTT.CCY, WTT.TRADE_MARKET, NVL(FP.FINPROD_ABBR, FP.FINPROD_NAME) finprodAbbr, TO_CHAR(WTT.VDATE, 'yyyy-MM-dd') VDATE, TO_CHAR(WTT.MDATE, 'yyyy-MM-dd') MDATE, TO_CHAR(WTT.TRADE_DATE, 'yyyy-MM-dd') TRADE_DATE, WTT.SHARE_AMT*100 amount, WTT.FPRICE_AMT tradeAmt, wtt.WORKFLOW_ID, WTT.INT_AMT, WPTT.THEORY_INT, WPTT.THEORY_AMT FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL WTT LEFT JOIN WFL_TRD_DEAL_TOTAL_ADD WTTA ON WTT.TOTLE_TRADE_ID = WTTA.TOTLE_TRADE_ID LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL WPTT ON WTT.TOTLE_TRADE_ID = WPTT.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT FP ON WTT.FINPROD_ID = FP.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SSAI ON SSAI.SEC_ACCT_ID = WTT.SEC_MANAGE_ACCT_ID LEFT JOIN PTL_PORTFOLIO PP ON PP.PORTFOLIO_ID = WTT.PORTFOLIO_ID LEFT JOIN MST_COUNTER_PARTY MCP ON WTT.COUNTER_ID = MCP.COUNTER_ID WHERE WTT.FINPROD_TYPE2 = 'F01' AND WTT.TG_BUSI_TYPE IN ('137', '138') AND WTTA.MP_FINPROD_ID IS NOT NULL AND WTT.PORTFOLIO_ID
ORDER BY WTT.MDATE)
UNION ALL
select * from ( SELECT '01' statusValid, null TOTLE_TRADE_ID, t8.TRADE_ID MP_FINPROD_ID, t8.tradeType, listagg(t8.CASH_TYPE, ',') WITHIN group (order by t8.cash_id) cashType, t8.PORTFOLIO_ID, t8.PORTFOLIO_NAME, MCP.COUNTER_NAME, t8.SEC_MANAGE_ACCT_ID, ssai.SEC_ACCT_NAME, fp.FINPROD_MARKET_ID, FP.FINPROD_ID, t8.CCY, t8.TRADE_MARKET, NVL(fp.FINPROD_ABBR, fp.FINPROD_NAME) finprodAbbr, TO_CHAR(min(t8.VDATE), 'yyyy-MM-dd') VDATE, TO_CHAR(t8.MDATE, 'yyyy-MM-dd') MDATE, null TRADE_DATE, t8.AMOUNT amount, null tradeAmt, NULL WORKFLOW_ID, null INT_AMT, SUM(T8.INT_AMT) THEORY_INT, SUM(t8.PRIN_AMT + t8.INT_AMT) THEORY_AMT FROM ( SELECT ASP.TRADE_ID, ASP.FINPROD_ID, ASP.SHARE_AMT AMOUNT, ASP.tradeType, ASP.SEC_MANAGE_ACCT_ID, ASP.PORTFOLIO_ID, ASP.PORTFOLIO_NAME, ASP.COUNTER_ID, ASP.CCY, ASP.TRADE_MARKET, ASP.CASH_TYPE, ASP.CASH_ID, ASP.VDATE, ASP.MDATE, ASP.PAY_DATE, SUM(NVL(ASP.PRIN_AMT, 0) * ASP.SHARE_AMT/100) PRIN_AMT /*债券借贷交易的share_amt存的是券面总额*/, SUM(NVL(ASP.INT_AMT, 0) * ASP.SHARE_AMT/100) INT_AMT FROM ( SELECT * FROM ( SELECT TPD.TRADE_ID, /*金融产品交易表.交易编号 交易编号*/ FCP.FINPROD_ID, /* 金融产品交易表.金融产品代码 金融产品代码*/ TPD.SHARE_AMT, /* 金融产品交易表.交易份额 数量*/ CASE WHEN TPD.FINPROD_TYPE2 = 'F29' THEN '137' ELSE '138' END tradeType, /* CASE 金融产品交易表.金融产品类型（投管分类） when 'F29' THEN 数据字典.投管业务类型.融入债券付息还本（付） ELSE 数据字典.投管业务类型.融出债券收息还本（收） END 类型*/ TPD.SEC_MANAGE_ACCT_ID, /* 金融产品交易表.证券管理户代码 证券管理账户*/ PP.PORTFOLIO_ID, /* 金融产品交易附属表.组合代码 组合代码*/ PP.PORTFOLIO_NAME, /* 组合.组合名称 组合名称*/ TPD.COUNTER_ID, TPD.ccy, TPD.TRADE_MARKET, FCP.VDATE, /* 现金流计划.调整后的计算开始日 计划开始日*/ FCP.MDATE, /* 现金流计划.调整后的计算结束日 计划结束日*/ FCP.CASH_AMT, /* 现金流计划.计划支付现金流 计划支付现金流*/ FCP.PRIN_AMT, /* 现金流计划.计划支付本金 计划支付本金*/ FCP.INT_AMT, /* 现金流计划.计划支付利息 计划支付利息*/ FCP.CASH_ID, /* 现金流计划.现金流代码 现金流代码*/ FCP.CASH_TYPE, /* 现金流计划.现金流类型 现金流类型*/ FCP.PAY_DATE /* 现金流计划.调整后的计划支付日 计划支付日*/
FROM TRD_PRODUCT_DEAL TPD INNER JOIN TRD_PRODUCT_DEAL_ADD TPDA ON TPD.TRADE_ID = TPDA.TRADE_ID INNER JOIN FIN_DEAL_TARGET FDT ON TPD.TRADE_ID = FDT.FINPROD_ID INNER JOIN FIN_CASH_PLAN FCP ON FCP.FINPROD_ID = FDT.PLEDGE_FINPROD_ID AND fcp.MDATE > tpd.TRADE_DATE AND tpd.MDATE >= fcp.MDATE INNER JOIN PTL_TRADE PT ON TPD.TRADE_ID = PT.BUSI_NO INNER JOIN PTL_PORTFOLIO pp ON PT.PORTFOLIO_ID = pp.PORTFOLIO_ID AND PP.INVEST_YESORNO = 'Y' WHERE tpd.FINPROD_TYPE2 IN ('F29', 'F30') AND tpd.TRADE_STATUS = '01' AND tpd.IS_CANCEL = 'N' AND FCP.CASH_TYPE IN ('01', '02', '03', '04') AND (fcp.PRIN_AMT > 0 OR fcp.INT_AMT > 0) AND NOT EXISTS( SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL tt INNER JOIN TRD_DEAL_TOTAL_ADD ta ON tt.TOTLE_TRADE_ID = ta.TOTLE_TRADE_ID WHERE tt.TRADE_STATUS = '01' AND tt.IS_CANCEL = 'N' AND tt.MDATE = fcp.MDATE AND TT.FINPROD_ID = FCP.FINPROD_ID AND TT.PORTFOLIO_ID = PT.PORTFOLIO_ID AND TA.MP_FINPROD_ID = TPD.TRADE_ID ) AND NOT EXISTS( SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL tt INNER JOIN WFL_TRD_DEAL_TOTAL_ADD ta ON tt.TOTLE_TRADE_ID = ta.TOTLE_TRADE_ID WHERE tt.TRADE_STATUS = '01' AND tt.IS_CANCEL = 'N' AND tt.MDATE = fcp.MDATE AND TT.FINPROD_ID = FCP.FINPROD_ID AND TT.PORTFOLIO_ID = PT.PORTFOLIO_ID AND TA.MP_FINPROD_ID = TPD.TRADE_ID )
AND pp.PORTFOLIO_ID
AND TPD.TRADE_ID = #{busiCode}
AND FCP.FINPROD_ID = #{finprodId}
AND ((pp.PORTFOLIO_ID IN
null) or pp.PORTFOLIO_ID in (
#{item}
) OR (pp.PARENT_PORTFOLIO_ID IN
null) or pp.PARENT_PORTFOLIO_ID in (
#{item} ))
AND TPD.COUNTER_ID = #{counterId}
AND tpd.FINPROD_TYPE2 = 'F29'
AND tpd.FINPROD_TYPE2 = 'F30'
AND FCP.PAY_DATE >= to_date(#{mdateStart}, 'yyyy-MM-dd')
AND FCP.PAY_DATE <= to_date(#{mdateEnd}, 'yyyy-MM-dd')
) ) ASP GROUP BY ASP.TRADE_ID, ASP.FINPROD_ID, ASP.SHARE_AMT, ASP.tradeType, ASP.SEC_MANAGE_ACCT_ID, ASP.CCY, ASP.TRADE_MARKET, ASP.PORTFOLIO_ID, ASP.PORTFOLIO_NAME, ASP.CASH_TYPE, ASP.CASH_ID, ASP.VDATE, ASP.MDATE, ASP.COUNTER_ID, ASP.PAY_DATE) T8 LEFT JOIN FIN_PRODUCT FP ON T8.FINPROD_ID = FP.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SSAI ON SSAI.SEC_ACCT_ID = T8.SEC_MANAGE_ACCT_ID LEFT JOIN MST_COUNTER_PARTY MCP ON T8.COUNTER_ID = MCP.COUNTER_ID GROUP BY t8.TRADE_ID, t8.tradeType, t8.PORTFOLIO_NAME, t8.PORTFOLIO_ID, t8.SEC_MANAGE_ACCT_ID, t8.ccy, t8.TRADE_MARKET, ssai.SEC_ACCT_NAME, fp.FINPROD_MARKET_ID, FP.FINPROD_ID, fp.FINPROD_ABBR, fp.FINPROD_NAME, MCP.COUNTER_NAME, t8.mdate, t8.AMOUNT order by t8.mdate )
UNION ALL
/*有效数据*/ select * from ( SELECT '05' statusValid, WTT.TOTLE_TRADE_ID, WTTA.MP_FINPROD_ID, WTT.TG_BUSI_TYPE tradeType, WTT.PS cashType, WTT.PORTFOLIO_ID, PP.PORTFOLIO_NAME, MCP.COUNTER_NAME, WTT.SEC_MANAGE_ACCT_ID, SSAI.SEC_ACCT_NAME, FP.FINPROD_MARKET_ID, FP.FINPROD_ID,WTT.CCY, WTT.TRADE_MARKET, NVL(FP.FINPROD_ABBR, FP.FINPROD_NAME) finprodAbbr, TO_CHAR(WTT.VDATE, 'yyyy-MM-dd') VDATE, TO_CHAR(WTT.MDATE, 'yyyy-MM-dd') MDATE, TO_CHAR(WTT.TRADE_DATE, 'yyyy-MM-dd') TRADE_DATE, TPD.SHARE_AMT amount, WTT.FPRICE_AMT tradeAmt, null WORKFLOW_ID, WTT.INT_AMT, WPTT.THEORY_INT, WPTT.THEORY_AMT FROM TRD_FIN_PRODUCT_DEAL_TOTAL WTT LEFT JOIN TRD_DEAL_TOTAL_ADD WTTA ON WTT.TOTLE_TRADE_ID = WTTA.TOTLE_TRADE_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL WPTT ON WTT.TOTLE_TRADE_ID = WPTT.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT FP ON WTT.FINPROD_ID = FP.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SSAI ON SSAI.SEC_ACCT_ID = WTT.SEC_MANAGE_ACCT_ID LEFT JOIN PTL_PORTFOLIO PP ON PP.PORTFOLIO_ID = WTT.PORTFOLIO_ID LEFT JOIN MST_COUNTER_PARTY MCP ON WTT.COUNTER_ID = MCP.COUNTER_ID LEFT JOIN TRD_PRODUCT_DEAL TPD ON WTTA.MP_FINPROD_ID = TPD.TRADE_ID WHERE WTT.FINPROD_TYPE2 = 'F01' AND WTT.TRADE_STATUS = '01' AND WTT.IS_CANCEL = 'N' AND WTT.TG_BUSI_TYPE IN ('137', '138') AND WTTA.MP_FINPROD_ID IS NOT NULL AND WTT.PORTFOLIO_ID
ORDER BY WTT.MDATE )
/*撤销数据*/
UNION ALL
SELECT * FROM ( SELECT '06' statusValid, WTT.TOTLE_TRADE_ID, WTTA.MP_FINPROD_ID, WTT.TG_BUSI_TYPE tradeType, WTT.PS cashType, WTT.PORTFOLIO_ID, PP.PORTFOLIO_NAME, MCP.COUNTER_NAME, WTT.SEC_MANAGE_ACCT_ID, SSAI.SEC_ACCT_NAME, FP.FINPROD_MARKET_ID, FP.FINPROD_ID, WTT.CCY, WTT.TRADE_MARKET, NVL(FP.FINPROD_ABBR, FP.FINPROD_NAME) finprodAbbr, TO_CHAR(WTT.VDATE, 'yyyy-MM-dd') VDATE, TO_CHAR(WTT.MDATE, 'yyyy-MM-dd') MDATE, TO_CHAR(WTT.TRADE_DATE, 'yyyy-MM-dd') TRADE_DATE, TPD.SHARE_AMT amount, WTT.FPRICE_AMT tradeAmt, null WORKFLOW_ID, WTT.INT_AMT, WPTT.THEORY_INT, WPTT.THEORY_AMT FROM TRD_FIN_PRODUCT_DEAL_TOTAL WTT LEFT JOIN TRD_DEAL_TOTAL_ADD WTTA ON WTT.TOTLE_TRADE_ID = WTTA.TOTLE_TRADE_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL WPTT ON WTT.TOTLE_TRADE_ID = WPTT.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT FP ON WTT.FINPROD_ID = FP.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SSAI ON SSAI.SEC_ACCT_ID = WTT.SEC_MANAGE_ACCT_ID LEFT JOIN PTL_PORTFOLIO PP ON PP.PORTFOLIO_ID = WTT.PORTFOLIO_ID LEFT JOIN MST_COUNTER_PARTY MCP ON WTT.COUNTER_ID = MCP.COUNTER_ID LEFT JOIN TRD_PRODUCT_DEAL TPD ON WTTA.MP_FINPROD_ID = TPD.TRADE_ID WHERE WTT.FINPROD_TYPE2 = 'F01' AND WTT.TRADE_STATUS = '03' AND WTT.IS_CANCEL = 'N' AND WTT.TG_BUSI_TYPE IN ('137', '138') AND WTTA.MP_FINPROD_ID IS NOT NULL AND WTT.PORTFOLIO_ID
ORDER BY WTT.MDATE)
)

